import { NextRequest, NextResponse } from "next/server";

const CANONICAL_HOST = "misaki38-ai.com";

export function middleware(request: NextRequest) {
  const host =
    request.headers.get("host")?.split(":")[0]?.toLowerCase() ?? "";

  if (host === "misaki.vercel.app") {
    const url = request.nextUrl.clone();
    url.protocol = "https:";
    url.host = CANONICAL_HOST;
    url.port = "";

    return NextResponse.redirect(url, 308);
  }

  // /api/chat は安全ラッパーを経由させる。
  // ラッパー側で「覚えてる？」系だけ history を空にしてから
  // 既存の app/api/chat/route.ts の POST を呼ぶ。
  if (request.nextUrl.pathname === "/api/chat") {
    const url = request.nextUrl.clone();
    url.pathname = "/api/chat-proxy";

    return NextResponse.rewrite(url);
  }

  return NextResponse.next();
}

export const config = {
  matcher: "/((?!_next/static|_next/image|favicon.ico).*)",
};

{
  "name": "misaki",
  "version": "1.0.0",
  "private": true,
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start",
    "test": "node --test --experimental-strip-types tests/*.test.ts tests/*.test.cjs"
  },
  "dependencies": {
    "@supabase/supabase-js": "^2.57.4",
    "next": "15.5.24",
    "openai": "5.0.0",
    "react": "19.1.1",
    "react-dom": "19.1.1",
    "web-push": "^3.6.7"
  },
  "devDependencies": {
    "@types/node": "^20",
    "@types/react": "^19",
    "@types/react-dom": "^19",
    "@types/web-push": "^3.6.4",
    "typescript": "^5"
  }
}

