function structuredEvidence(memory:string[]):LifeEvidence[]{return memory.slice(-20).map(decodeStructured).filter((x):x is StructuredLifeFact=>!!x).filter(x=>x.fact&&x.source==="user"&&x.confidence>=.55).filter(x=>{if(!x.validUntil)return false;const until=Date.parse(x.validUntil);return Number.isFinite(until)&&until>=Date.now()}).map(x=>({text:x.fact,source:"structured_memory" as const,sentAt:x.observedAt,freshness:age(x.observedAt)}))}
function items(history:ChatMessage[],memory:string[]):LifeEvidence[]{const remembered=memory.slice(-20).filter(text=>!text.startsWith(LIFE_MEMORY_PREFIX)).map(text=>({text:normalize(text),source:"memory" as const,sentAt:null,freshness:"unknown" as const}));const structured=structuredEvidence(memory);const recent=history.filter(x=>x.role==="user").slice(-16).map(x=>({text:normalize(x.text),source:"recent_user" as const,sentAt:x.sentAt??null,freshness:age(x.sentAt)}));return[...remembered,...structured,...recent].filter(x=>x.text)}
function lastMatch(xs:LifeEvidence[],patterns:RegExp[]){for(let i=xs.length-1;i>=0;i--){const x=xs[i];if(patterns.some(p=>p.test(x.text)))return{...x,text:x.text.slice(0,120)}}return null}
function usable(x:LifeEvidence|null){if(!x)return false;if(x.source==="structured_memory")return true;if(x.source!=="recent_user")return false;if(x.freshness!=="fresh"&&x.freshness!=="recent")return false;if(/(?:今日|きょう|今夜|今は|これから|明日|あした)/.test(x.text))return x.freshness==="fresh";return true}
export function buildProactiveLifeContext(history:ChatMessage[],memory:string[]):ProactiveLifeContext{const xs=items(history,memory),s=lastMatch(xs,SITUATION_PATTERNS),p=lastMatch(xs,PLAN_PATTERNS),valid=[s,p].filter((x):x is LifeEvidence=>usable(x));const evidence=[...new Set(valid.map(x=>x.text))];return{situation:usable(s)?s!.text:"none",plan:usable(p)?p!.text:"none",evidence,evidenceItems:valid,confidence:evidence.length?"explicit":"none"}}
export function createProactiveLifeGuide(c:ProactiveLifeContext){if(c.confidence==="none")return`【ユーザーの生活文脈】\n今回、自発メッセージで現在の生活・予定として使える新しい本人発言はありません。\n保存済み記憶や古い発言だけから、現在地、勤務中、休み、睡眠、体調、予定を推測しないでください。`;return`【ユーザーの生活文脈：本人発言ベース】\n現在の状況として参照できる発言: ${c.situation}\n予定として参照できる発言: ${c.plan}\n\n使える根拠:\n${c.evidenceItems.map(x=>`・[${x.source}/${x.freshness}] ${x.text}`).join("\n")}\n\n重要:\n・現在の生活状況には fresh / recent の本人発言、または期限内の構造化生活記憶だけを使う\n・普通の保存済み記憶は関係の背景には使えても、現在の生活状況の証拠にはしない\n・期限切れ・壊れた構造化生活記憶を現在の根拠にしない\n・古い発言を「今もそうだ」と断定しない\n・根拠の範囲を越えて場所、勤務、体調、予定を作らない`}

